import math


def min_speed_brute(piles: list[int], h: int) -> int:
    k = 1
    while True:
        if sum(math.ceil(p / k) for p in piles) <= h:
            return k
        k += 1

def min_eating_speed(piles: list[int], h: int) -> int:
    def hours(k: int) -> int:
        return sum((p + k - 1) // k for p in piles)

    lo, hi = 1, max(piles)
    while lo < hi:
        mid = lo + (hi - lo) // 2
        if hours(mid) <= h:
            hi = mid
        else:
            lo = mid + 1
    return lo
